for (const [locale, translations] of Object.entries(RR_REVIEWED_MEDIA_TEXT)) {
  const target = globalThis.RR_REVIEWED_TRANSLATIONS.text[locale];
  RR_REVIEWED_MEDIA_TEXT_KEYS.forEach((key, index) => {
    target[key] = translations[index];
  });
}
